import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"
DATA = DOCS / "data"
ASSETS = DOCS / "assets"
REPO = "https://github.com/buffedlizard55-lab/GEMSDOE47"
OFFICIAL = "https://www.drivendata.org/competitions/306/competition-doe-gems/"


def e(value) -> str:
    return html.escape(str(value), quote=True)


def a(url: str, label: str, **attrs) -> str:
    extras = " ".join(f'{k.rstrip("_").replace("_", "-")}="{e(v)}"' for k, v in attrs.items())
    return f'<a href="{e(url)}" {extras}>{e(label)}</a>'


def table(headers, rows) -> str:
    return '<div class="table-scroll"><table><thead><tr>' + ''.join(f'<th scope="col">{e(h)}</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows) + '</tbody></table></div>'


def shell(title: str, description: str, content: str, *, prefix="", active="") -> str:
    nav = [("executive-summary.html", "Summary"), ("hypotheses.html", "Hypotheses"),
           ("evidence.html", "Evidence"), ("sources.html", "Sources & feed"), ("submit.html", "Submission guide")]
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{e(title)} · GEMSDOE47</title><meta name="description" content="{e(description)}">
<meta name="theme-color" content="#173d38"><link rel="icon" href="{prefix}assets/mark.svg" type="image/svg+xml">
<link rel="stylesheet" href="{prefix}assets/site.css"><script src="{prefix}assets/site.js" defer></script></head>
<body data-site-version="h47c" data-base="{prefix}"><a class="skip" href="#main">Skip to evidence</a>
<header class="masthead"><a class="brand" href="{prefix}index.html"><span class="brand-mark" aria-hidden="true">G/47</span><span>GEMSDOE47<small>Fault mapping research</small></span></a>
<nav aria-label="Main navigation">{''.join(a(prefix+f,l,aria_current='page' if f==active else 'false') for f,l in nav)}</nav>{a(REPO,'Repository ↗',class_='repo-link')}</header>
<div class="status-bar"><span class="status-dot" aria-hidden="true"></span><strong>Research-only · NOT PROMOTED</strong><span>No slot authorized. Do not upload this run.</span></div>
<main id="main">{content}<section class="session-history"><h2>Preserved concurrent research</h2><p><a href="{prefix}session3.html">Session 3 scarp persistence</a> · <a href="{prefix}research.html">H48 curvature consensus</a> · <a href="{prefix}all-downloads.html">All historical research files</a>. Different proxy frames; no cross-task/private guarantee. Every submission slot gate remains closed.</p></section></main><footer><div><strong>Maximize P(Win).</strong> Preserve the slot when the evidence says no.<br><strong>Own the Outcome.</strong> Publish the bytes, failures and corrections.</div><div>{a(prefix+'irregularities.html','Limitations & corrections')}<br>{a(prefix+'method.html','Reproduce this screen')} · {a(prefix+'leaderboard.html','Dated public board')}<br>Reviewed 6 October 2026 · {a(OFFICIAL,'Official competition 306 ↗')}</div></footer></body></html>'''


def read(path):
    return json.loads((ROOT / path).read_text())


def make_preview(filename: str) -> None:
    """Actual downsampled grid preview, not generated geology or a stock map."""
    import numpy as np
    import rasterio
    sys.path.insert(0, str(ROOT / "src"))
    from gems47 import grid as G
    t = G.load_template()
    with rasterio.open(DOCS / "downloads" / filename) as source:
        p = source.read(1) > 0
    def pool(x):
        h, w = x.shape
        padded = np.pad(x, ((0, (-h) % 4), (0, (-w) % 4)))
        return padded.reshape(padded.shape[0] // 4, 4, padded.shape[1] // 4, 4).max(axis=(1, 3))
    footprint, catalogue, prediction = pool(t.footprint), pool(t.catalogue), pool(p)
    image = np.empty((*footprint.shape, 3), np.uint8); image[:] = (248, 247, 242)
    image[footprint] = (216, 225, 220)
    image[catalogue] = (72, 107, 144)
    image[prediction] = (187, 82, 45)
    def chunk(kind, payload):
        return struct.pack('>I', len(payload)) + kind + payload + struct.pack('>I', zlib.crc32(kind + payload) & 0xffffffff)
    raw = b''.join(b'\x00' + image[row].tobytes() for row in range(image.shape[0]))
    png = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', image.shape[1], image.shape[0], 8, 2, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(raw, 9)) + chunk(b'IEND', b'')
    (ASSETS / "prediction-preview.png").write_bytes(png)


def main() -> int:
    DATA.mkdir(exist_ok=True); ASSETS.mkdir(exist_ok=True)
    screen = read("evidence/profile-screen.json")
    submission = read("evidence/current-submission.json")
    audit = read("evidence/profile-uniqueness.json")
    if submission["slot_authorized"] or screen["screen_gate"]["slot_authorized"]:
        raise ValueError("this renderer cannot label an unreviewed run as an eligible submission")
    if not submission["format_validation"]["format_valid"] or not audit["bounded_unique"] or audit["exact_matches"]:
        raise ValueError("format and bounded uniqueness audits must both pass before publication")
    tiff = DOCS / "downloads" / submission["filename"]
    if hashlib.sha256(tiff.read_bytes()).hexdigest() != submission["format_validation"]["sha256"]:
        raise ValueError("download bytes do not match the export receipt")
    copy_receipts = ["current-submission.json", "profile-screen.json", "profile-blocks.json",
                     "profile-spacing-history.csv", "profile-uniqueness.json", "prior-inventory-20261006.json",
                     "profile-control-flow-recheck.json", "research-environment.json", "leaderboard-read-20261006.json", "merge-publication-receipt.json"]
    for name in copy_receipts:
        shutil.copyfile(ROOT / "evidence" / name, DATA / name)
    shutil.copyfile(ROOT / "data" / "restore_receipt.json", DATA / "restore-receipt.json")
    for name in ("official-download-probes.json", "three-pass-review.json", "band-audit.json", "requirements-audit.json"):
        if (ROOT / "evidence" / name).exists():
            shutil.copyfile(ROOT / "evidence" / name, DATA / name)
    for name in ("current-source-list.json", "irregularities.json"):
        shutil.copyfile(ROOT / "registry" / name, DATA / name)
    # Retired run is publicly inspectable but never the current validation receipt.
    retired = DATA / "retired-profile-pass1"; retired.mkdir(exist_ok=True)
    for path in (ROOT / "evidence" / "retired-profile-pass1").iterdir():
        shutil.copyfile(path, retired / path.name)
    make_preview(submission["filename"])
    s = screen["screen_gate"]; band = screen["conformal"]; spacing = submission["chosen_spacing_px"]
    sha = submission["format_validation"]["sha256"]
    n_comp = audit["comparisons"]
    def download(prefix=""):
        return f'''<div class="download-panel"><div><span class="eyebrow">Newly inferred · {submission['format_validation']['bytes']:,} bytes</span><h2>One file. Full official grid.</h2><p>Not a renamed prior submission. New H47-C1 inference; <strong>research-only, not for submission</strong>.</p></div><div class="actions">{a(prefix+'downloads/'+submission['filename'],'↓ Download GeoTIFF',class_='button primary',download='')}{a(prefix+'downloads/'+submission['zip']['filename'],'Single-TIFF ZIP',class_='button secondary',download='')}{a(prefix+'data/current-submission.json','Validation receipt',class_='text-link')}</div><p class="filename">{e(submission['filename'])}</p><p class="export-confidence">Spacing {spacing:g} px / {spacing*100:g} m · nominal 90% marginal block band · floor 0.0000 · NOT private/global</p><p class="hash">SHA-256 <code>{sha}</code></p></div>'''
    def decision():
        return f'''<div class="notice"><strong>DO NOT UPLOAD · no slot</strong><p>The locked holdout gate failed: pooled DTI {s['candidate_pooled_dti']:.6f} is below the frozen baseline’s {s['incumbent_pooled_dti']:.6f}; only {s['candidate_block_wins']}/{s['truth_bearing_blocks']} truth-bearing blocks improve (required {s['required_block_wins']}). The lower floor is zero. Local format validity is not scientific promotion or organizer acceptance.</p></div>'''
    def confidence():
        return f'''<div class="confidence"><strong>Selected spacing {spacing:g} px / {spacing*100:g} m · nominal 90% marginal block band · lower floor 0.0000</strong><p>Selection/calibration: {band['n_selection']}/{band['n_calibration']} disjoint-role blocks, not adaptive leaderboard scores. Simultaneous over five spacings; rank {band['rank_1_based']}/{band['n_calibration']}. Exchangeability is assumed and unverified. <strong>No private-score, pooled-map, geographic-conditional or global-artifact guarantee.</strong></p></div>'''
    comparisons = table(["Locked test comparison", "Pooled DTI", "Mean block DTI", "Spacing"], [
        ["H47-C1 profile detector", f"<strong>{s['candidate_pooled_dti']:.6f}</strong>",f"{s['candidate_mean_dti']:.6f}","2.8 px"],
        ["Ordinary-terrain + raw-band baseline",f"<strong>{s['incumbent_pooled_dti']:.6f}</strong>",f"{s['incumbent_mean_dti']:.6f}","3.6 px"],
        ["Fixed-seed spaced random",f"{s['random_pooled_dti']:.6f}",f"{s['random_mean_dti']:.6f}","2.8 px"]])
    hero = '''<section class="hero"><div><span class="eyebrow">Geologic Enhanced Mapping System · competition 306</span><h1>New predictions.<br>Evidence before a slot.</h1><p class="lede">A geological hypothesis becomes useful only when it survives the controls. The new odd-step versus channel detector is complete, independently packaged, and honestly <em>not promoted</em>.</p></div><figure class="map-card"><img src="assets/prediction-preview.png" alt="Actual north-up GeoDAWN grid: known catalogue traces in blue and newly inferred research dots in orange." width="823" height="933"><figcaption>Actual output preview · north up · EPSG:32611<br><span class="legend blue"></span>public catalogue <span class="legend orange"></span>new research dots<br>4× downsampling; not confirmed new faults.</figcaption></figure></section>'''
    stats = f'''<div class="stats"><div><strong>37,654</strong><span>new unit-dot predictions</span></div><div><strong>{s['candidate_pooled_dti']:.6f}</strong><span>local public-catalogue DTI</span></div><div><strong>0.0000</strong><span>90% marginal proxy floor</span></div><div><strong>0</strong><span>competition slots spent</span></div></div>'''
    uniqueness = f'''<p><strong>Bounded uniqueness:</strong> {n_comp} prior-raster comparisons across {audit['public_repositories_in_inventory']} public repository inventories, plus local history; zero exact positive-mask or in-footprint value matches. Maximum mask Jaccard {audit['max_jaccard']:.4f}. Excluded inventory objects are listed with their actual reasons in the audit (including wrong-grid/multiband or non-single-TIFF archives). Standalone H33 TIFFs were compared. Unpublished/inaccessible outputs are not covered; this is not global uniqueness or proof of geological discovery.</p>{a('data/profile-uniqueness.json','Every comparison, source commit and blob hash →')}'''
    index = download() + hero + stats + decision() + confidence() + f'''<section><div class="section-head"><span class="eyebrow">The actual result</span><h2>Better than random. Not better than the control.</h2></div>{comparisons}<p>The slight mean-block gain does not rescue the pooled loss. Selection and promotion rules were fixed before test interpretation. No leaderboard score is claimed for this TIFF.</p>{a('executive-summary.html','Read the executive summary →',class_='text-link')}</section><section class="two-col"><article><span class="eyebrow">What is genuinely new</span><h2>Scarp shape, not just an edge.</h2><p>Remove affine terrain slope from cross-profiles; compare an odd step template with an even channel/ridge template. Add along-strike consistency and gravity-normal agreement to raw features. No prior submission field or catalogue-distance feature constructs the candidate.</p>{a('hypotheses.html','Five preregistered hypotheses →')}</article><article><span class="eyebrow">What was checked</span><h2>15 / 15 local format checks.</h2><p>One float32 data band. Raw samples are finite in [0,1]; an internal TIFF validity mask marks exactly the template’s outside-footprint pixels as null. CRS, 100 m resolution, dimensions, bounds and affine transform match. No .msk sidecar.</p>{a('submit.html','Range-error defense & submission guide →')}</article></section><section><h2>A genuinely different prediction, with a bounded audit.</h2>{uniqueness}</section><section class="feed-card"><span class="eyebrow">Automatic source feed</span><h2>Official facts and dated observations stay separate.</h2><p id="feed-status">Last official board read: 6 October 2026. Permitted-source refresh status loads from JSON; DrivenData queries are disabled without written permission.</p><p>Saved leader <strong class="live-top-score">0.3774</strong> · user target <strong>0.3195</strong> · this TIFF <strong>UNSCORED</strong>.</p>{a('sources.html','Open sources, hashes and availability →')} · {a('data/source-feed.json','Download the deployed feed JSON')}</section>'''
    pages = {"index.html": ("Fault mapping, evidence first", "A genuinely new H47-C1 GeoTIFF, strict range/mask checks, blocked validation and honest zero conformal floor.", index)}
    name_note = f'''<h2>Name and short note</h2><p>Identifiers for this <strong>research run</strong>, not permission to use a slot.</p><p><code id="submission-name">{e(submission['submission_name'])}</code> <button data-copy-id="submission-name">Copy name</button></p><pre id="portal-note">{e(submission['portal_note'])}</pre><button data-copy-id="portal-note">Copy short note</button><p>{submission['portal_note_characters']} characters. Do not replace “UNSCORED; NOT PROMOTED” with a projected score.</p>'''
    steps = f'''<h2 id="submit-steps">Exact submission sequence — only after a new candidate is approved</h2><ol class="steps"><li>Open {a(OFFICIAL,'the official competition overview')} and select <strong>Compete!</strong> to enroll. Read the {a('https://docs.nlr.gov/docs/fy26osti/96647.pdf','official rules')} and certify your own eligibility. Account access is not performed or bypassed here.</li><li>First verify the <strong>new candidate’s</strong> published report explicitly passes the predeclared spatial holdout gate, provenance requirements and three-pass review. <strong>This C1 report does not pass. Stop here for this file.</strong></li><li>For an approved candidate, download its GeoTIFF, verify its SHA-256, and confirm one float32 band on the template grid with values [0,1] and null outside. The official problem specifies a GeoTIFF; use a one-TIFF ZIP only if the authenticated upload form requests an archive. The supplied research ZIP contains exactly its byte-identical TIFF, with no JSON, notes or sidecar.</li><li>In the competition sidebar select <strong>Submit → Make new submission</strong> (the official overview’s sequence). Choose the approved file. Where the form offers a Name or Note field, paste that candidate’s unique name and short note; do not claim a proxy estimate as its leaderboard result.</li><li>Submit only within the official <strong>three-scoring-submissions-per-week</strong> limit. Save the organizer receipt, final filename, hash, score and timestamp. Local validation does not establish portal acceptance. If rejected, retain the exact uploaded bytes and error; diagnose before spending another slot.</li><li>Before the deadline, choose <strong>one</strong> eligible submission for both prize rounds. The final round re-scores the same selected file after expert label expansion; there is no unlimited-submission final phase. Disclose generative-AI assistance in the required narrative and retain reproducible code/data licenses.</li></ol><p>The overview currently lists <strong>3 December 2026, 23:59 UTC</strong> as competition end; always consult the official rules/portal for operative deadlines. No competition upload was made by this repository.</p>'''
    summary = download() + '''<section class="page-heading"><span class="eyebrow">Executive summary · reviewed 6 October 2026</span><h1>The deliverable is new.<br>The gate is still closed.</h1><p class="lede">H47-C1 tests a physical scarp-versus-channel signature on actual restored inputs. It fails the declared promotion rule. No winning score or private guarantee is fabricated.</p></section>''' + decision() + confidence() + f'''<section><h2>Completed end to end</h2><ul class="checklist"><li>23 / 23 SHA-256-pinned mirror files restored; core grid independently verified. Mirror identity is not organizer authentication.</li><li>Five new hypotheses ranked before implementation; code/protocol committed at {a(REPO+'/commit/cc14ad84fbace93bdd0c2a7bc8b520170e082bb3','cc14ad8')} before fitting. Corrected selection-variable control flow was committed at {a(REPO+'/commit/7aa938e','7aa938e')} without model or parameter changes.</li><li>64 training, 21 selection, 21 calibration, 23 test blocks; 2 km guards per side; only training-core labels form targets. Same-mass tests use 4,993 predictions and 7,690 public truth pixels.</li><li>New 37,654-dot full-grid TIFF and single-file ZIP; 15 strict format checks; {n_comp} bounded prior-art comparisons, no exact match.</li><li>Negative result, all spacings, raw components, block IDs and superseded run retained. No slot spent.</li></ul>{comparisons}<p>Off-catalogue SGMC diagnostic: profile {screen['secondary_sgmc_pooled_dti']['profile']:.6f}, random {screen['secondary_sgmc_pooled_dti']['random']:.6f}, ordinary-terrain {screen['secondary_sgmc_pooled_dti']['structural']:.6f}, H33 geometry re-emitted at matched mass {screen['secondary_sgmc_pooled_dti']['h33_geometry_reemitted']:.6f}. This also does not support promotion.</p></section><section><h2>Why the reported GEMSDOE32 best can improve through pruning</h2><p>The user reports H33/B2 at 0.2778. Owner pages describe mass/precision pruning of flank/rung predictions, not an authenticated new geological signal. Exact filename-to-score mapping remains unresolved. The DTI algebra explains why removing predictions with low incremental true credit and high false-positive cost can raise a score. It does not prove which TIFF earned that number or justify deleting every catalogue flank.</p>{a('analysis.html','Mechanism, conditional target algebra and evidence limits →')}</section><section><h2>What is not achieved</h2><p>This run has <strong>not</strong> beaten 0.3195 or the saved official leader 0.3774. Its local catalogue proxy is not numerically comparable to those private/new-fault competition scores. No positive private-score floor exists. Raw 1 m DEM tiles and the supplied tile-link CSV were not acquired here; the 100 m descriptors are not 1 m geomorphology.</p></section><section>{name_note}{steps}</section>'''
    pages["executive-summary.html"] = ("Executive summary", "New research GeoTIFF download, actual blocked scores, zero confidence floor, limitations and official submission sequence.", summary)
    hypotheses = table(["Rank / hypothesis", "Inputs and derived signature", "Missing-catalogue rationale / difference", "Expected value / cost", "Status"], [
        ["1 · C1 odd step vs even channel", "Band 12 detrended elevation; band 13 gravity. Affine-detrended erf step versus Gaussian channel; four cross-directions, widths 1/2 sampling steps; along-strike continuity; gravity-normal agreement.", "A persistent signed topographic offset differs from a valley/ridge edge. Does not use catalogue distance, historical masks or leaderboard-derived features.", "Best first information/cost trade-off; modest plausible improvement, no numerical DTI forecast. About 4 min on 2 CPU cores for the fixed screen.", "Implemented; failed promotion. 100 m data cannot date metre-scale scarps."],
        ["2 · C2 geophysical lag", "TMI horizontal/vertical slopes, isostatic gravity and conductivity. Signed normal-profile change points at 100–400 m cross-layer lags, not same-pixel product.", "Buried faults may produce laterally displaced contrasts; require consistent direction/lag, unlike prior edge-strength or TMI persistence rankings.", "Plausible medium value; moderate CPU cost, uncertain transfer.", "Not implemented. Existing raw arrays available as mirrors; official meaning of tc is unresolved."],
        ["3 · C3 contact rejection", "GeoDAWN K/Th/U ratios and magnetic/terrain edges. Penalize broad lithologic/radiometric contacts without a local signed step or strain support.", "Discriminates non-fault contacts rather than promoting all geophysical edges. Radiometry is not itself fault truth.", "Potential precision gain; low/moderate compute; may reject real faults at contacts.", "Not implemented. Extension rasters restored; official source/license listed, contractor semantics not authenticated."],
        ["4 · C4 displaced drainage / paleodischarge", "Detrended terrain and official GDR paleogeothermal/well-spring vectors. Drainage-segment offsets, saddle continuity and localized discharge support, not proximity alone.", "Fault-controlled drainage/discharge can persist without a catalogue trace. Requires explicit non-tectonic drainage controls.", "Uncertain expected value; moderate geometric work, source coverage first.", "Not implemented. Official-byte/coverage probe recorded separately; never used in C1."],
        ["5 · C5 raw 1 m occupancy/connectivity", "Official 3DEP DEM tiles; detrended multiscale scarp templates, channel/road confounder controls, aggregate oriented segment occupancy/connectivity to the 100 m grid.", "Preserves narrow landforms erased by 100 m averaging; materially different from mirrored 12-band quantized lidar descriptors.", "Potentially highest physical upside; highest storage/I/O cost. No claim hidden faults or leaders use it.", "Not yet feasible end to end: official tile-link CSV, exact coverage and bytes not acquired. 3DEP is free; source listing is not a tile download."],
    ])
    pages["hypotheses.html"] = ("Five preregistered hypotheses", "Ranked physical hypotheses, precise layers and signatures, competing explanations, costs and feasibility.", f'''<section class="page-heading"><span class="eyebrow">Geology before optimization</span><h1>Five hypotheses.<br>One frozen first test.</h1><p class="lede">Qualitative expected-value ranks, not invented DTI forecasts. The top detector was preregistered before implementation and test scoring.</p></section><section>{hypotheses}<p>{a('research/h47c-hypotheses-preregistered.md','Original immutable preregistration')} · {a('research/h47c-review-notes.md','Technical correction and three-pass review notes')}</p><h2>Controls and confounders</h2><p>Ordinary terrain gradients and raw-band supervision are controls, not novelty. Channels, lithologic contacts, roads, erosional scarps, resampling artifacts and survey boundaries can imitate faults. A low-overlap mask is not proof that any prediction is a geological discovery. Staff explicitly withholds hidden test sources/types/coverage.</p><p>The template idea is informed by {a('https://agupubs.onlinelibrary.wiley.com/doi/full/10.1029/2018JB016886','Sare et al. (2019)')}, which used ≤2 m topography. This four-direction 100 m adaptation is not a replication, a morphologic age estimator or a claim of scientific invention.</p></section>{decision()}''')
    history = list(csv.DictReader((DATA / "profile-spacing-history.csv").open()))
    def average(role, model, d):
        rows = [r for r in history if r["role"]==role and r["model"]==model and float(r["spacing_px"])==d]
        return sum(float(r['DTI']) for r in rows) / len(rows)
    sweep = table(["Spacing (px / m)", "Selection mean", "Calibration mean", "90% lower floor", "Test mean (diagnostic only)"], [[f"{d:g} / {d*100:g}"+(' · LOCKED' if d==spacing else ''), f"{band['selection_centers'][i]:.6f}", f"{average('calibration','profile',d):.6f}", f"{band['lower_bounds'][i]:.4f}", f"{average('test','profile',d):.6f}"] for i,d in enumerate(screen['spacings_px'])])
    evidence_links = '<ul class="receipt-list">'+''.join(f'<li>{a("data/"+name,name)}</li>' for name in copy_receipts+['restore-receipt.json'])+'</ul>'
    pages["evidence.html"] = ("Experiment evidence", "Every spacing, fold, exact metric component and strict artifact receipt; negative results retained.", f'''<section class="page-heading"><span class="eyebrow">No cherry-picking</span><h1>The full spacing history.</h1><p class="lede">The operating point was selected before test interpretation. Do not choose a new spacing from this diagnostic test column.</p></section>{confidence()}<section>{sweep}{comparisons}<h2>Why the 90% floor is zero</h2><p>Calibration has 21 truth-bearing blocks, but three profile settings-vectors include zero credit. The rank-20 maximum residual is {band['quantile']:.9f}, equal to the selected mean center; subtracting it yields 0.0000. These difficult blocks were retained, not deleted. Ties and finite-rank arithmetic are tested. Conditional on exchangeability the simultaneous marginal rank coverage is at least 20/22 = 90.91%; geological exchangeability and private transfer are not verified.</p><h2>Exposure and scope</h2><p>Training / selection / calibration / test: 64 / 21 / 21 / 23 guarded blocks. Truth-bearing: 59 / 20 / 21 / 22. Feature-valid support 4,799,995 of 5,167,373 footprint pixels; public catalogue 60,988 pixels, 55,459 on support, 37,163 in guarded cores. Global 37,654-dot emission changes the proportional block quotas and masks catalogue pixels; therefore the band <strong>does not cover that global TIFF</strong>.</p><p>All public labels were accessible to prior sessions. This is a newly frozen re-screen, not pristine independent labels or an organizer private test. Predictions train only on training-core labels.</p><h2>Machine-readable receipts</h2>{evidence_links}<p>{a('data/retired-profile-pass1/retraction.json','Superseded first-run retraction')} · {a('data/retired-profile-pass1/profile-spacing-history.csv','Preserved first-run full history')}</p><p>The correction changed no trained field or per-setting score: all three prediction-field hashes and the full score-history hash match the first run byte-for-byte. Only the erroneous final operating point was corrected.</p></section>{decision()}''')
    method = f'''<section class="page-heading"><span class="eyebrow">Reproducible method</span><h1>A physical transform.<br>A guarded statistical screen.</h1></section><section><h2>Signal construction</h2><p>At offsets −6…6 along four grid directions, project elevation profiles and each template off an intercept and linear slope. Fit a signed erf step and an even Gaussian channel/ridge; retain normalized residual R², their difference, absolute height, along-strike continuity, width and gravity-normal agreement. Widths are <strong>1 or 2 sampling steps</strong>: axial samples are 100 m apart, diagonal samples √2×100 m. The directional bank is coarse, not rotationally isometric.</p><pre>step:    z(s) = a + b s + A erf(s / (√2 w))
channel: z(s) = a + b s + B exp(−s² / (2 w²))
competing physical explanations, not a fault-age estimate</pre><h2>Controlled models and splits</h2><p>19 raw bands; raw + 7 ordinary terrain derivatives; raw + terrain + 7 profile descriptors (33 columns). Same HistGradientBoostingRegressor: 150 iterations, learning rate .06, 15 leaves, min leaf 100, L2=2, no early stopping, seed 470610. Up to 180,000 inverse-probability-weighted samples; 90,000 kernel-positive cap. No coordinates, catalogue-distance or old prediction-field features.</p><p>16×16 deterministic block lattice; 20-pixel guards per side. 41×41 minimum filter rejects invalid raw support. Target kernels see only catalogue labels in training cores. Spaced unit-dot quota matched across candidate, selection-only incumbent and seeded random control. Emit spacings 1.5 / 2.8 / 3.6 / 4.6 / 5.8 px.</p><h2>Split conformal, accurately scoped</h2><p>Compute five selection means μⱼ. Each calibration block produces rᵢ=maxⱼ(μⱼ−DTIᵢⱼ). Choose order statistic k=ceil((n+1)×.90), augment with +∞ if k&gt;n, then Lⱼ=max(0,μⱼ−q). Select the largest floor, then selection mean, then larger spacing. A maximum over settings protects subsequent spacing choice <em>if block score vectors are exchangeable</em>; it is not a conditional geographic or private-score guarantee.</p><p>{a('https://www.stat.berkeley.edu/~ryantibs/papers/conformal.pdf','Lei et al., split-conformal theory')} establishes finite-sample marginal coverage under exchangeability. Adaptive leaderboard history is not an exchangeable calibration sample. A spatial guard removes local overlap, not geological domain shift.</p><h2>Run the complete pipeline</h2><pre>python3 -m venv .venv
.venv/bin/pip install -r requirements-dev.txt -r requirements-research-lock.txt
.venv/bin/python scripts/restore_data.py --group all
PYTHONPATH=src .venv/bin/python scripts/verify_grid.py
PYTHONPATH=src .venv/bin/python scripts/run_profile_experiment.py
PYTHONPATH=src .venv/bin/python scripts/build_profile_submission.py
.venv/bin/python scripts/audit_prior_artifacts.py --candidate docs/downloads/{e(submission['filename'])}
.venv/bin/python scripts/publish_research_site.py
PYTHONPATH=src .venv/bin/python -m pytest tests -q
.venv/bin/python -m ruff check .</pre><p>Requires configured GitHub access for pinned public mirrors, not a DrivenData password. Large arrays, weights and source downloads remain in ignored cache; the recipe regenerates them. Old LATI builders require an explicit educational opt-in and cannot overwrite Pages downloads. {a(REPO+'/blob/main/requirements-research-lock.txt','Exact numerical versions')} · {a('data/research-environment.json','Executed environment receipt')}</p><h2>AI and data disclosure</h2><p>An Arena.ai coding agent assisted research drafting, implementation, testing and documentation. The entrant must include generative-AI disclosure in the official narrative. Competition inputs are SHA-256-pinned public owner mirrors, not authenticated DrivenData downloads. Public official sources and any external licenses are itemized; none of the feasibility-probe vectors trains this C1 output.</p></section>'''
    pages["method.html"] = ("Method and reproduction", "Physical profile construction, weighted baseline models, guarded roles and correctly scoped conformal inference.", method)
    target_growth = lambda target: (target/(1-.2*target))/(.2778/(1-.2*.2778))-1
    analysis = f'''<section class="page-heading"><span class="eyebrow">Learning from the reported best</span><h1>Pruning can help.<br>It does not locate new geology.</h1></section><section><h2>What the 0.2778 evidence actually says</h2><p>The user associates 0.2778 with GEMSDOE32 H33/B2. A dated official participant row has the same value, but does not expose a filename. The owner’s page describes 37,654 dots, B2/flank pruning and an unscored projected 0.2747; other source histories disagree. Mirror hashes identify bytes, not the file that earned 0.2778. This conflict remains visible rather than being silently resolved.</p><h2>The exact mechanism</h2><pre>D = T / (0.2 (T + F) + 0.8 K)
ΔD &gt; 0 ⇔ ΔT (1 − 0.2 D) − 0.2 D ΔF &gt; 0
F = S − Φ;  T need not equal Φ</pre><p>Removing predictions can improve D if avoided false-positive cost exceeds lost max-kernel truth credit. Duplicated coverage and low-credit rungs/flanks are plausible pruning targets, <strong>not</strong> proof that all adjacent terrain is empty. A dot can credit several truth pixels; separated prediction dots alone do not justify T=Φ or D=T/(.2N+.8K).</p><h2>How large a real improvement is required?</h2><p>For the explicitly hypothetical case of fixed F and K, reaching 0.3195 from 0.2778 needs about <strong>{target_growth(.3195)*100:.1f}% more weighted true credit</strong>; reaching 0.3774 needs <strong>{target_growth(.3774)*100:.1f}% more</strong>. These are algebraic scenarios, not forecasts; T, F and K on hidden labels are not identified here.</p><h2>Why λ shrinking and history inversion do not create a free win</h2><pre>D(λp) = λT / (0.2 λ(T+F) + 0.8 K)
1/D(λp) = 0.2(1+F/T) + 0.8 K/(λT)</pre><p>For positive truth and credit, reducing confidence λ lowers D. Even exact scaling measurements identify ratios, not a unique hidden map or absolute truth mass. Nested/adaptive, rounded scores with unverified file mapping cannot supply conformal coverage. No three-slot λ-probe recommendation remains active.</p><h2>What the new test teaches</h2><p>C1 beats random on public catalogue cores but not the ordinary-terrain pooled control; it also loses to random on the distant SGMC diagnostic. The result does not warrant declaring all scarp methods falsified, nor does it support private transfer. Higher-resolution, properly licensed morphology is a next research direction only after byte/coverage feasibility and a genuinely fresh validation design.</p>{a('knowledge.html','Reusable knowledge and current next steps →')}</section>{decision()}'''
    pages["analysis.html"] = ("Mechanism and evidence boundaries", "Reported H33 pruning mechanism, exact DTI tradeoffs, non-identifiable hidden mass and no free confidence-scaling win.", analysis)
    irregularities = read("registry/irregularities.json")["irregularities"]
    irr_table = table(["ID / severity", "Issue", "Resolution or boundary"], [[f'<span id="{e(row["id"].lower())}">{e(row["id"])} · {e(row["severity"])}</span>', e(row['what']), e(row['what_was_done'])] for row in irregularities])
    pages["irregularities.html"] = ("Irregularities and review", "Visible provenance conflicts, selection correction, source failures, scalar ambiguity and withdrawn unsupported claims.", f'''<section class="page-heading"><span class="eyebrow">Own the corrections</span><h1>Uncertainty belongs<br>in the main report.</h1></section><section>{irr_table}<p>{a('research/h47c-review-notes.md','Three explicit review passes and technical correction')} · {a('data/irregularities.json','Irregularity registry JSON')} · {a('data/profile-control-flow-recheck.json','Unchanged fields/history proof')}</p><h2>Range failure is covered, not historically proved</h2><p>The exact rejected upload and organizer parser receipt were not supplied. NaNs, finite nodata sentinels, out-of-range raw features and external-mask dependence are possible mechanisms. The new file has none of them under independent raw and masked rasterio reads, but it has not been portal-tested. Do not claim that the original error’s cause or organizer acceptance has been established.</p></section>''')
    source_config = read("registry/current-source-list.json")
    official_rows = [[e(src['title']), a(src['url'],src['url']), e(src['evidence_class'])] for src in source_config['sources'] if src['evidence_class']!='secondary_owner_page']
    source_table = table(["Source", "Manual-review URL", "Evidence class"], official_rows)
    sources_content = f'''<section class="page-heading"><span class="eyebrow">Auditable research / data / knowledge</span><h1>Official facts.<br>Secondary reports.<br>Never the same thing.</h1><p class="lede">A successful fetch proves availability, not the truth of every sentence. Source hashes, dated observations and failure states are explicit. The daily feed is also published through the public GitHub Checks API; the browser uses that live receipt with a same-origin dated fallback. Existing main-root Pages publishing is retained.</p></section><section class="feed-card"><h2>Automatic permitted-source feed</h2><p><strong>Permission boundary:</strong> DrivenData Terms prohibit robots/spiders. No written permission or documented approved feed is recorded. Automatic DrivenData queries are disabled; the participant board is a retained dated observation, not a live monitor. <a href="https://www.drivendata.org/termsofuse/">Read Terms</a>.</p><p id="feed-status">Reading the deployed source-feed JSON…</p><p id="feed-timestamp"></p>{a('data/source-feed.json','Raw deployed feed JSON')} · {a('data/current-source-list.json','Versioned 65-URL registry')}<div id="source-feed-table" aria-live="polite"></div></section><section><h2>Official and primary review links</h2>{source_table}<h2>Official constraints checked on 6 October 2026</h2><ul><li>Target is new geological fault pixels, not spring/well locations; public/private spatial chunks; known catalogue pixels excluded in both prize rounds.</li><li>DTI: triangular 300 m / 3 px kernel, alpha .2, beta .8. Single float32 GeoTIFF, [0,1], EPSG:32611, 100 m grid and matching bounds; outside null/NaN.</li><li>Up to three scoring submissions per week; one selected file for both rounds; generative-AI disclosure and reproducible finalist package.</li><li>Staff does not disclose hidden test sources, types or coverage. A claim that hidden labels primarily use lidar is unsupported.</li><li>3DEP products are free without use restrictions. GDR 1391 is CC BY 4.0. Source listing alone does not verify bytes, footprint or proposed-feature feasibility.</li></ul><h2>Data restored and data not acquired</h2><p>23 pinned mirrors verified; {a('data/restore-receipt.json','restore receipt')}. Labels/template footprint has 5,167,373 pixels; catalogue 60,988; evaluated 5,106,385. The mirrored feature sentinel is finite float32-min, not NaN. Raw GeoDAWN contractor grids, 1 m DEM CSV/tiles and authenticated competition downloads are not claimed obtained. <a href="data/band-audit.json">All 19 literal band tags and semantic ambiguities</a>.</p><p>{a('data/prior-inventory-20261006.json','54 commit-pinned public repository inventories and narrative hashes')} cover user-named families through GEMSDOE54. The names “48GEMSDOE/49GEMSDOE” resolve in the visible owner inventory to GEMSDOE48/GEMSDOE49; not invented alternate Pages URLs. Owner narratives, including projections and scores, remain secondary. {a('prior-results.md','Supplied score history')} · {a('prior-results.csv','History CSV')}</p><h2>External-byte feasibility</h2><div id="official-probe-results"><p>GitHub-hosted probe verified official GDR trace/paleogeothermal bytes and coverage (82,871 line-covered pixels; 244 paleogeothermal point cells). USGS national traces cover 82,841 footprint pixels. These are not hidden fault labels and do not train C1. Read each actual source/geometry status.</p></div><p>{a(REPO+'/actions/workflows/source-probes.yml','Official download-probe workflow')} · {a('data/official-download-probes.json','Last official-byte/coverage receipt')}</p></section>'''
    pages["sources.html"] = ("Sources and automatic feed", "Official sources, pinned mirrors, dated leader observations, external data feasibility and automatic failure-safe refresh.", sources_content)
    submission_content = '''<section class="page-heading"><span class="eyebrow">Format is necessary, not sufficient</span><h1>A valid TIFF.<br>Not an eligible slot.</h1></section>''' + download() + decision() + confidence() + f'''<section><h2>Defense against “Predicted values must be in range [0, 1]”</h2><p>The new file stores only finite zero/one raw samples. An internal TIFF mask marks the 7,111,787 outside-footprint pixels invalid/null. Valid zero predictions remain valid because <code>nodata=None</code>; there is no .msk sidecar or extra data band. Raw min/max 0/1, zero NaNs/infinities, zero out-of-range pixels, zero positive catalogue/outside pixels.</p><p>All 15 independent read-back checks pass. Grid: width 3292 × height 3730, EPSG:32611, 100 m; affine [100,0,243350,0,−100,4508550]; bounds [243350,4135550,572550,4508550]. {a('https://gdal.org/en/stable/drivers/raster/gtiff.html#internal-nodata-masks','GDAL internal-mask specification')} · {a('https://rasterio.readthedocs.io/en/stable/topics/masks.html','Rasterio mask interpretation')}.</p><p>A parser that ignores masks still sees [0,1]; a GDAL masked reader sees null exactly outside the footprint. <strong>Organizer mask acceptance has not been tested.</strong> A strict writer rejects non-finite or out-of-range interior values before float32 conversion; it never silently clips them.</p>{name_note}{steps}</section>'''
    pages["submit.html"] = ("Submission and range-error guide", "Strict new GeoTIFF, exact identifier and short note, official submission steps and closed scientific slot gate.", submission_content)
    pages["portal-checklist.html"] = ("Portal checklist", "Do not upload the unpromoted run; official ordered submission and receipt-retention checklist.", '<section class="page-heading"><span class="eyebrow">Portal checklist</span><h1>Approval first.<br>Then upload.</h1></section>'+decision()+f'<section>{steps}{name_note}</section>')
    pages["leaderboard.html"] = ("Dated official leaderboard", "Participant scores from the official public page, separate from unscored TIFFs and incomplete owner score histories.", f'''<section class="page-heading"><span class="eyebrow">Public participant observations</span><h1>Leaderboards are not<br>file-score receipts.</h1></section><section><p id="feed-status">Saved official page read: 6 October 2026. Leader 0.3774; DARD 0.3195 / rank 7; extradr19 0.2778 / rank 13. The feed marks failed or stale refreshes.</p><div id="leaderboard-table"></div><p>{a(OFFICIAL+'leaderboard/','Open official leaderboard ↗')} · {a('data/source-feed.json','Deployed feed JSON')} · {a('data/leaderboard-read-20261006.json','Preserved dated observation')}</p><h2>Current artifact: UNSCORED</h2><p>No organizer return exists for H47-C1. The proxy 0.177872 is not an estimate of its public/private leaderboard score. The user target 0.3195 and saved top score 0.3774 have not been surpassed by this work.</p><h2>Owner history is learning material</h2><p>{a('prior-results.md','All supplied variants and unscored entries')} · {a('prior-results.csv','Machine-readable supplied history')}. Blank/missing scores are not filled with zero. Do not use adaptively chosen, correlated variants to form a coverage guarantee.</p></section>''')
    pages["knowledge.html"] = ("Reusable knowledge and next work", "What survives the audit, source constraints, conditional next hypotheses and an autonomous recovery recipe.", '''<section class="page-heading"><span class="eyebrow">Reusable knowledge base</span><h1>Keep the mechanism.<br>Drop the overclaim.</h1></section><section><h2>Established here</h2><ul><li>Exact DTI and max-kernel arithmetic; empty truth gets no phantom corner credit; finite-score metric components can be independently rechecked.</li><li>Changing raw confidence downward is not a free score gain. Sparse prediction spacing does not imply T=Φ.</li><li>Affine-detrended odd/even profiles distinguish synthetic scarps and channels, but do not improve the locked pooled catalogue control in this run.</li><li>Feature sentinel, sample-mask semantics, 100 m morphology limits and disputed tc/depth metadata are visible rather than reinterpreted as authoritative geology.</li><li>Low mask overlap establishes different output geometry only, not validated discoveries.</li></ul><h2>Next work, in order</h2><ol><li>Keep this slot closed. Retain exact bytes and reports; do not rename it as promoted.</li><li>Complete official core-data authentication only through an authorized entrant workflow; never bypass login. Mirrors already restore autonomously.</li><li>Use the actual official-byte/coverage probe before ranking external-data hypotheses as viable. Acquire the official 1m_DEM_links.csv and bounded licensed DEM tiles; log tiles, masks, coverage and checksum manifest.</li><li>Preregister a high-resolution, competing-explanation detector and a new validation design. The current test scores are now known; they cannot be an independent tuning/test pair for a modified C1 arm.</li><li>Compare same-mass candidate, ordinary-terrain and random controls plus relevant off-catalogue geometry; require the declared gate and positive supported floor before any scarce slot.</li><li>Re-audit artifact uniqueness and strict mask/range semantics; publish download and receipt only with its actual research/promoted status.</li></ol><p>The hidden label sources and winner architecture are not disclosed. There is no evidence here for a universal 100 m data ceiling or exact hidden truth mass.</p></section>''')
    for filename, (title, description, body) in pages.items():
        (DOCS / filename).write_text(shell(title, description, body, active=filename))
    root_index = index.replace('src="assets/', 'src="docs/assets/').replace('href="downloads/', 'href="docs/downloads/').replace('href="data/', 'href="docs/data/')
